INSERT IGNORE INTO scent_families (id, name, slug, intro, sort_order, is_active, seo_title, seo_description, created_at, updated_at) VALUES (1, 'Fresh & Citrus', 'fresh-citrus', 'Bergamot, lemon, aromatic herbs and clean musks. Fragrances that stay legible at 42°C and never turn sweet on skin — the ones we hand people first.', 10, 1, 'Fresh & Citrus Perfumes | Sky Fragrances', 'Fresh, citrus and aromatic eau de parfum built for Pakistani summers. Long-lasting, 50ml and 100ml, cash on delivery nationwide.', '2026-09-25 10:00:00', NULL);
INSERT IGNORE INTO scent_families (id, name, slug, intro, sort_order, is_active, seo_title, seo_description, created_at, updated_at) VALUES (2, 'Floral', 'floral', 'Rose, peony, orange blossom, iris and jasmine. From luminous morning florals to soft powdery skin scents, none of them heavy and none of them shy.', 20, 1, 'Floral Perfumes | Sky Fragrances', 'Rose, peony, iris and orange blossom eau de parfum. Long-lasting floral fragrances for her and unisex, 50ml and 100ml, COD across Pakistan.', '2026-09-25 10:00:00', NULL);
INSERT IGNORE INTO scent_families (id, name, slug, intro, sort_order, is_active, seo_title, seo_description, created_at, updated_at) VALUES (3, 'Amber & Spice', 'amber-spice', 'Saffron, cinnamon, amber, vanilla and resins. Warmth you can see — built for Pakistani winters, weddings and evenings that run late.', 30, 1, 'Amber & Spice Perfumes | Sky Fragrances', 'Saffron, amber, vanilla and leather eau de parfum for evenings and weddings. Long-lasting, 50ml and 100ml, cash on delivery in Pakistan.', '2026-09-25 10:00:00', NULL);
INSERT IGNORE INTO scent_families (id, name, slug, intro, sort_order, is_active, seo_title, seo_description, created_at, updated_at) VALUES (4, 'Oud & Smoke', 'oud-smoke', 'Laotian oud, smoked leather, incense and birch tar. Our deepest work, and the fragrances people recognise before they see you.', 40, 1, 'Oud & Smoke Perfumes | Sky Fragrances', 'Oud, leather and incense eau de parfum with serious longevity. For him and unisex, 50ml and 100ml, cash on delivery across Pakistan.', '2026-09-25 10:00:00', NULL);
INSERT IGNORE INTO scent_families (id, name, slug, intro, sort_order, is_active, seo_title, seo_description, created_at, updated_at) VALUES (5, 'Green & Earthy', 'green-earthy', 'Vetiver, petrichor, cypress and moss. The smell of the first rain on hot ground, with not one sweet note in the range.', 50, 1, 'Green & Earthy Perfumes | Sky Fragrances', 'Vetiver, petrichor and green woody eau de parfum. The smell of the monsoon, bottled. 50ml and 100ml, COD nationwide.', '2026-09-25 10:00:00', NULL);
INSERT IGNORE INTO collections (id, name, slug, tagline, description, mood, image, sort_order, is_active, show_on_home, seo_title, seo_description, created_at, updated_at) VALUES (1, 'Dawn Chorus', 'dawn-chorus', 'The hour the light arrives', 'The first hour, before the city is loud. Soft florals, milky woods and citrus that reads as light rather than sharpness.', 'Optimism, a clean start, the scent of a good morning.', 'collections/dawn-chorus.webp', 10, 1, 1, 'Dawn Chorus Collection | Sky Fragrances', 'Luminous florals and soft citrus eau de parfum for the start of the day. Long-lasting, 50ml and 100ml. Cash on delivery across Pakistan.', '2026-09-25 10:00:00', NULL);
INSERT IGNORE INTO collections (id, name, slug, tagline, description, mood, image, sort_order, is_active, show_on_home, seo_title, seo_description, created_at, updated_at) VALUES (2, 'Azure Heights', 'azure-heights', 'Freshness that survives the heat', 'Fragrance built for a Pakistani summer. Clean, airy compositions that stay legible at 42°C and never turn sweet on skin.', 'Clarity and composure. Daylight, air, room to breathe.', 'collections/azure-heights.webp', 20, 1, 1, 'Azure Heights Collection | Sky Fragrances', 'Crisp, weightless eau de parfum made for hot weather. Fresh citrus, musk and white florals in 50ml and 100ml. COD nationwide.', '2026-09-25 10:00:00', NULL);
INSERT IGNORE INTO collections (id, name, slug, tagline, description, mood, image, sort_order, is_active, show_on_home, seo_title, seo_description, created_at, updated_at) VALUES (3, 'Golden Hour', 'golden-hour', 'The warmest point of the day', 'Warmth you can see. Saffron, amber, rose absolute and resins, blended to glow rather than shout.', 'Indulgence and glow. Being looked at, and not minding.', 'collections/golden-hour.webp', 30, 1, 1, 'Golden Hour Collection | Sky Fragrances', 'Saffron, amber and rose eau de parfum for evenings and celebrations. Long-lasting, 50ml and 100ml. Cash on delivery across Pakistan.', '2026-09-25 10:00:00', NULL);
INSERT IGNORE INTO collections (id, name, slug, tagline, description, mood, image, sort_order, is_active, show_on_home, seo_title, seo_description, created_at, updated_at) VALUES (4, 'Midnight Meridian', 'midnight-meridian', 'The darkest part of the sky', 'Our deepest work. Oud, leather, incense and smoke — the collection we are asked about most, and the one we are slowest to release.', 'Authority and mystery. The fragrance people remember.', 'collections/midnight-meridian.webp', 40, 1, 1, 'Midnight Meridian Collection | Sky Fragrances', 'Oud, leather and incense fragrances for evening wear. Long-lasting eau de parfum in 50ml and 100ml. Cash on delivery across Pakistan.', '2026-09-25 10:00:00', NULL);
INSERT IGNORE INTO collections (id, name, slug, tagline, description, mood, image, sort_order, is_active, show_on_home, seo_title, seo_description, created_at, updated_at) VALUES (5, 'Monsoon Veil', 'monsoon-veil', 'After the first rain', 'The smell of the first rain on hot ground. Green, mineral and earthy, with not one sweet note in the range.', 'Nostalgia and relief. Barsaat, bottled.', 'collections/monsoon-veil.webp', 50, 1, 1, 'Monsoon Veil Collection | Sky Fragrances', 'Petrichor, vetiver and green eau de parfum inspired by the monsoon. Unisex and for him, 50ml and 100ml. COD nationwide.', '2026-09-25 10:00:00', NULL);
INSERT IGNORE INTO products (id, collection_id, name, slug, gender, scent_family, short_description, description, notes_top, notes_heart, notes_base, longevity, sillage, best_season, occasion, is_featured, is_new, is_active, sort_order, sales_count, rating_avg, rating_count, published_at, deleted_at, seo_title, seo_description, created_at, updated_at) VALUES (1, (SELECT c.id FROM collections c WHERE c.slug = 'midnight-meridian'), 'Azure Oud', 'azure-oud', 'unisex', 'Oud & Smoke', 'Laotian oud and Turkish rose under a cold blue sky.', 'Oud, cooled. We set the warmest material in perfumery against a cold blue sky: juniper and violet leaf hovering over a heart of Laotian oud and Turkish rose. It stays close through the day and opens like night air after dark, which is why it is the one people recognise before they see you.', 'Calabrian Bergamot, Juniper Berry, Violet Leaf, Pink Pepper', 'Laotian Oud, Turkish Rose, Nutmeg', 'Amberwood, Cedarwood, Labdanum, Vetiver', 5, 4, 'Autumn & Winter', 'Evening, Signature', 1, 0, 1, 10, 0, 0.00, 0, '2026-06-01 10:00:00', NULL, 'Azure Oud Eau de Parfum | Sky Fragrances', 'Laotian oud, Turkish rose and cool violet leaf — our signature unisex eau de parfum. 50ml and 100ml. Cash on delivery across Pakistan.', '2026-06-01 10:00:00', NULL);
INSERT IGNORE INTO products (id, collection_id, name, slug, gender, scent_family, short_description, description, notes_top, notes_heart, notes_base, longevity, sillage, best_season, occasion, is_featured, is_new, is_active, sort_order, sales_count, rating_avg, rating_count, published_at, deleted_at, seo_title, seo_description, created_at, updated_at) VALUES (2, (SELECT c.id FROM collections c WHERE c.slug = 'azure-heights'), 'Cirrus', 'cirrus', 'unisex', 'Fresh & Citrus', 'Bergamot, iris and white musk — the cleanest thing we make.', 'The cleanest thing we make. Bergamot and green mandarin over a weightless heart of iris and jasmine air, drying down to white musk and blond cedar. Wear it to be noticed at the second glance rather than the first.', 'Calabrian Bergamot, Green Mandarin, Pink Peppercorn', 'Iris, Jasmine Petals, Lavender', 'White Musk, Blond Cedar, Ambrette', 3, 2, 'Spring & Summer', 'Daily, Office', 1, 0, 1, 20, 0, 0.00, 0, '2026-06-01 10:00:00', NULL, 'Cirrus Eau de Parfum — Fresh Unisex | Sky Fragrances', 'A weightless bergamot, iris and white musk eau de parfum built for Pakistani summers. 50ml and 100ml, cash on delivery nationwide.', '2026-06-01 10:00:00', NULL);
INSERT IGNORE INTO products (id, collection_id, name, slug, gender, scent_family, short_description, description, notes_top, notes_heart, notes_base, longevity, sillage, best_season, occasion, is_featured, is_new, is_active, sort_order, sales_count, rating_avg, rating_count, published_at, deleted_at, seo_title, seo_description, created_at, updated_at) VALUES (3, (SELECT c.id FROM collections c WHERE c.slug = 'dawn-chorus'), 'Aurora Bloom', 'aurora-bloom', 'her', 'Floral', 'Lychee, peony and Damask rose over warm vanilla musk.', 'Dawn, at the moment colour arrives. Lychee and blackcurrant break over peony and Damask rose, then settle into a warm vanilla musk that is still on skin long after the morning. Our most gifted fragrance, and the one customers come back for.', 'Lychee, Blackcurrant, Mandarin', 'Peony, Damask Rose, Magnolia', 'Vanilla, White Musk, Sandalwood, Cashmeran', 4, 4, 'Spring, wearable all year', 'Daytime, Gifting, Celebrations', 1, 0, 1, 30, 0, 0.00, 0, '2026-06-01 10:00:00', NULL, 'Aurora Bloom Eau de Parfum for Her | Sky Fragrances', 'Lychee, peony and Damask rose over warm vanilla musk. A long-lasting floral eau de parfum for her in 50ml and 100ml. COD across Pakistan.', '2026-06-01 10:00:00', NULL);
INSERT IGNORE INTO products (id, collection_id, name, slug, gender, scent_family, short_description, description, notes_top, notes_heart, notes_base, longevity, sillage, best_season, occasion, is_featured, is_new, is_active, sort_order, sales_count, rating_avg, rating_count, published_at, deleted_at, seo_title, seo_description, created_at, updated_at) VALUES (4, (SELECT c.id FROM collections c WHERE c.slug = 'midnight-meridian'), 'Stratus Noir', 'stratus-noir', 'him', 'Oud & Smoke', 'Smoked leather, incense and birch tar before the storm.', 'A low ceiling of cloud before a storm. Cardamom and grapefruit peel give way to smoked leather, incense and dry birch tar, held together by patchouli and tonka. Severe, expensive, and not built to be liked by everyone.', 'Grapefruit Peel, Cardamom, Black Pepper', 'Smoked Leather, Incense, Orris', 'Birch Tar, Patchouli, Tonka Bean, Vetiver', 5, 4, 'Autumn & Winter', 'Evening, Formal', 1, 0, 1, 40, 0, 0.00, 0, '2026-06-01 10:00:00', NULL, 'Stratus Noir Eau de Parfum for Him | Sky Fragrances', 'Smoked leather, incense and birch tar — a dark, long-lasting eau de parfum for him. 50ml and 100ml, cash on delivery across Pakistan.', '2026-06-01 10:00:00', NULL);
INSERT IGNORE INTO products (id, collection_id, name, slug, gender, scent_family, short_description, description, notes_top, notes_heart, notes_base, longevity, sillage, best_season, occasion, is_featured, is_new, is_active, sort_order, sales_count, rating_avg, rating_count, published_at, deleted_at, seo_title, seo_description, created_at, updated_at) VALUES (5, (SELECT c.id FROM collections c WHERE c.slug = 'midnight-meridian'), 'Eclipse Velvet', 'eclipse-velvet', 'her', 'Amber & Spice', 'Saffron, tuberose and black vanilla drawn across the shoulders.', 'Total darkness, then warmth. Saffron and plum sink into tuberose and a black vanilla accord, with benzoin and cacao absolute closing it like velvet drawn across the shoulders. Two sprays at night are enough.', 'Saffron, Plum, Bitter Almond', 'Tuberose, Jasmine Sambac, Osmanthus', 'Black Vanilla, Benzoin, Cacao Absolute, Sandalwood', 5, 5, 'Winter', 'Evening, Weddings', 0, 0, 1, 50, 0, 0.00, 0, '2026-06-01 10:00:00', NULL, 'Eclipse Velvet Eau de Parfum for Her | Sky Fragrances', 'Saffron, tuberose and black vanilla — an intense evening eau de parfum for her. Long-lasting, 50ml and 100ml. COD nationwide.', '2026-06-01 10:00:00', NULL);
INSERT IGNORE INTO products (id, collection_id, name, slug, gender, scent_family, short_description, description, notes_top, notes_heart, notes_base, longevity, sillage, best_season, occasion, is_featured, is_new, is_active, sort_order, sales_count, rating_avg, rating_count, published_at, deleted_at, seo_title, seo_description, created_at, updated_at) VALUES (6, (SELECT c.id FROM collections c WHERE c.slug = 'azure-heights'), 'Zephyr Blanc', 'zephyr-blanc', 'her', 'Floral', 'Neroli, orange blossom and white musk in moving air.', 'White flowers in moving air. Neroli and pear open onto orange blossom and jasmine that never turn heavy, kept bright by musk and a whisper of coconut wood. For the woman who wants presence without volume.', 'Neroli, Pear, Italian Lemon', 'Orange Blossom, Jasmine Grandiflorum, Ylang-Ylang', 'White Musk, Coconut Wood, Cedar', 3, 3, 'Spring & Summer', 'Daily, Daytime', 0, 1, 1, 60, 0, 0.00, 0, '2026-09-15 10:00:00', NULL, 'Zephyr Blanc Eau de Parfum for Her | Sky Fragrances', 'Neroli, orange blossom and white musk — a soft floral eau de parfum for her, made for warm weather. 50ml and 100ml, COD in Pakistan.', '2026-09-15 10:00:00', NULL);
INSERT IGNORE INTO products (id, collection_id, name, slug, gender, scent_family, short_description, description, notes_top, notes_heart, notes_base, longevity, sillage, best_season, occasion, is_featured, is_new, is_active, sort_order, sales_count, rating_avg, rating_count, published_at, deleted_at, seo_title, seo_description, created_at, updated_at) VALUES (7, (SELECT c.id FROM collections c WHERE c.slug = 'azure-heights'), 'Silver Lining', 'silver-lining', 'him', 'Fresh & Citrus', 'Sicilian lemon, lavender and vetiver — crisp in Karachi heat.', 'The light behind the cloud. Sicilian lemon and sage lift a clean heart of lavender and geranium, finishing on vetiver, ambroxan and moss — crisp in Karachi heat and still there at the end of the day. The one we hand people first.', 'Sicilian Lemon, Sage, Grapefruit', 'Lavender, Geranium, Nutmeg', 'Vetiver, Ambroxan, Oakmoss, Musk', 4, 3, 'Summer, wearable all year', 'Daily, Office', 1, 0, 1, 70, 0, 0.00, 0, '2026-06-01 10:00:00', NULL, 'Silver Lining Eau de Parfum for Him | Sky Fragrances', 'Sicilian lemon, lavender and vetiver — a crisp everyday eau de parfum for him that survives the heat. 50ml and 100ml, COD nationwide.', '2026-06-01 10:00:00', NULL);
INSERT IGNORE INTO products (id, collection_id, name, slug, gender, scent_family, short_description, description, notes_top, notes_heart, notes_base, longevity, sillage, best_season, occasion, is_featured, is_new, is_active, sort_order, sales_count, rating_avg, rating_count, published_at, deleted_at, seo_title, seo_description, created_at, updated_at) VALUES (8, (SELECT c.id FROM collections c WHERE c.slug = 'dawn-chorus'), 'Cumulus Cashmere', 'cumulus-cashmere', 'unisex', 'Floral', 'Iris, cashmere woods and clean musk — skin, softened.', 'Skin, softened. Almond milk and bergamot melt into iris and heliotrope over cashmere woods and a clean musk that reads as your own skin on a better day. The one to wear when you would rather not think about what you are wearing.', 'Bergamot, Almond Milk, Pink Pepper', 'Iris, Heliotrope, Violet', 'Cashmeran, White Musk, Sandalwood, Tonka Bean', 3, 2, 'All year', 'Daily, Layering', 0, 1, 1, 80, 0, 0.00, 0, '2026-09-15 10:00:00', NULL, 'Cumulus Cashmere Eau de Parfum | Sky Fragrances', 'Iris, cashmere woods and clean musk — a soft unisex skin scent for everyday wear. 50ml and 100ml, cash on delivery across Pakistan.', '2026-09-15 10:00:00', NULL);
INSERT IGNORE INTO products (id, collection_id, name, slug, gender, scent_family, short_description, description, notes_top, notes_heart, notes_base, longevity, sillage, best_season, occasion, is_featured, is_new, is_active, sort_order, sales_count, rating_avg, rating_count, published_at, deleted_at, seo_title, seo_description, created_at, updated_at) VALUES (9, (SELECT c.id FROM collections c WHERE c.slug = 'golden-hour'), 'Saffron Zenith', 'saffron-zenith', 'him', 'Amber & Spice', 'Kashmiri saffron, amber leather and oud at the sun''s highest point.', 'The sun at its highest point. Kashmiri saffron and cinnamon burn over an amber-leather heart, grounded in oud and Atlas cedar that hold for a full working day. Built for the Pakistani winter, and for men who get told they smell expensive.', 'Kashmiri Saffron, Cinnamon, Bergamot', 'Amber Accord, Leather, Rose Absolute', 'Oud, Atlas Cedar, Labdanum, Musk', 5, 4, 'Autumn & Winter', 'Evening, Formal, Weddings', 1, 0, 1, 90, 0, 0.00, 0, '2026-06-01 10:00:00', NULL, 'Saffron Zenith Eau de Parfum for Him | Sky Fragrances', 'Kashmiri saffron, amber leather and oud — a rich winter eau de parfum for him. Long-lasting, 50ml and 100ml. COD across Pakistan.', '2026-06-01 10:00:00', NULL);
INSERT IGNORE INTO products (id, collection_id, name, slug, gender, scent_family, short_description, description, notes_top, notes_heart, notes_base, longevity, sillage, best_season, occasion, is_featured, is_new, is_active, sort_order, sales_count, rating_avg, rating_count, published_at, deleted_at, seo_title, seo_description, created_at, updated_at) VALUES (10, (SELECT c.id FROM collections c WHERE c.slug = 'golden-hour'), 'Halo Rose', 'halo-rose', 'her', 'Amber & Spice', 'Turkish rose absolute wrapped in saffron, oud and amber.', 'A ring of light around the sun. Turkish rose absolute at full strength, deepened with raspberry and saffron, then wrapped in oud, amber and a little smoke. Heirloom-grade rose for people who think they have smelled every rose.', 'Raspberry, Saffron, Pink Pepper', 'Turkish Rose Absolute, Geranium, Clove', 'Oud, Amber, Patchouli, Vanilla', 5, 4, 'Autumn & Winter', 'Evening, Weddings, Gifting', 0, 0, 1, 100, 0, 0.00, 0, '2026-06-01 10:00:00', NULL, 'Halo Rose Eau de Parfum for Her | Sky Fragrances', 'Turkish rose absolute with saffron, oud and amber — a rich rose eau de parfum for her. 50ml and 100ml, cash on delivery in Pakistan.', '2026-06-01 10:00:00', NULL);
INSERT IGNORE INTO products (id, collection_id, name, slug, gender, scent_family, short_description, description, notes_top, notes_heart, notes_base, longevity, sillage, best_season, occasion, is_featured, is_new, is_active, sort_order, sales_count, rating_avg, rating_count, published_at, deleted_at, seo_title, seo_description, created_at, updated_at) VALUES (11, (SELECT c.id FROM collections c WHERE c.slug = 'monsoon-veil'), 'Nimbus Rain', 'nimbus-rain', 'unisex', 'Green & Earthy', 'Green mandarin, petrichor and vetiver — the first rain on hot ground.', 'The first rain on hot ground. Green mandarin and violet leaf over a wet-earth accord of vetiver, cypress and mineral petrichor — the air in Islamabad in August. Nostalgia, bottled, without a single sweet note.', 'Green Mandarin, Violet Leaf, Juniper', 'Petrichor Accord, Cypress, Geranium', 'Vetiver, Patchouli, Ambergris Accord, Moss', 4, 3, 'Monsoon & Summer', 'Daily, Outdoors', 0, 1, 1, 110, 0, 0.00, 0, '2026-09-15 10:00:00', NULL, 'Nimbus Rain Eau de Parfum — Petrichor | Sky Fragrances', 'Green mandarin, petrichor and vetiver — the smell of the first rain, as a unisex eau de parfum. 50ml and 100ml, COD nationwide.', '2026-09-15 10:00:00', NULL);
INSERT IGNORE INTO products (id, collection_id, name, slug, gender, scent_family, short_description, description, notes_top, notes_heart, notes_base, longevity, sillage, best_season, occasion, is_featured, is_new, is_active, sort_order, sales_count, rating_avg, rating_count, published_at, deleted_at, seo_title, seo_description, created_at, updated_at) VALUES (12, (SELECT c.id FROM collections c WHERE c.slug = 'monsoon-veil'), 'Vetiver Squall', 'vetiver-squall', 'him', 'Green & Earthy', 'Smoked Haitian vetiver, grapefruit and dry tobacco leaf.', 'Wind ahead of the rain. Haitian vetiver, smoked and salted, cut with grapefruit and black pepper, finishing on cedar and dry tobacco leaf. Sharp, green and unmistakably masculine without raising its voice.', 'Grapefruit, Black Pepper, Bergamot', 'Haitian Vetiver, Clary Sage, Cardamom', 'Cedarwood, Tobacco Leaf, Ambrox, Musk', 4, 3, 'Autumn, wearable all year', 'Daily, Office, Evening', 0, 1, 1, 120, 0, 0.00, 0, '2026-09-15 10:00:00', NULL, 'Vetiver Squall Eau de Parfum for Him | Sky Fragrances', 'Smoked Haitian vetiver with grapefruit, cedar and tobacco leaf. A green woody eau de parfum for him, 50ml and 100ml. COD in Pakistan.', '2026-09-15 10:00:00', NULL);
