INSERT IGNORE INTO reviews (id, product_id, customer_name, customer_city, rating, title, body, status, is_sample, ip_hash, moderated_by, created_at, approved_at, rejected_at) VALUES (1, (SELECT p.id FROM products p WHERE p.slug = 'azure-oud'), 'Bilal A.', 'Lahore', 5, 'Compliments every single time', 'Ordered the 100ml after trying a friend''s bottle. It is still on my shirt collar the next morning. Delivery to Lahore took two days.', 'pending', 1, NULL, NULL, '2026-08-14 19:22:00', NULL, NULL);
INSERT IGNORE INTO reviews (id, product_id, customer_name, customer_city, rating, title, body, status, is_sample, ip_hash, moderated_by, created_at, approved_at, rejected_at) VALUES (2, (SELECT p.id FROM products p WHERE p.slug = 'azure-oud'), 'Hina S.', 'Karachi', 4, 'Beautiful, but I wanted more sillage', 'The oud is smooth and never harsh, and it lasts all day on me. I just expected it to fill a room a little more than it does. Still my favourite for evenings.', 'pending', 1, NULL, NULL, '2026-08-22 14:10:00', NULL, NULL);
INSERT IGNORE INTO reviews (id, product_id, customer_name, customer_city, rating, title, body, status, is_sample, ip_hash, moderated_by, created_at, approved_at, rejected_at) VALUES (3, (SELECT p.id FROM products p WHERE p.slug = 'aurora-bloom'), 'Mariam K.', 'Islamabad', 5, 'My signature now', 'I have worn the same imported floral for years and this replaced it in a week. The rose and lychee opening is gorgeous and the vanilla dry-down is soft, not sugary.', 'pending', 1, NULL, NULL, '2026-08-30 11:45:00', NULL, NULL);
INSERT IGNORE INTO reviews (id, product_id, customer_name, customer_city, rating, title, body, status, is_sample, ip_hash, moderated_by, created_at, approved_at, rejected_at) VALUES (4, (SELECT p.id FROM products p WHERE p.slug = 'aurora-bloom'), 'Zoya R.', 'Faisalabad', 5, 'Lasts a full working day', 'Two sprays at 8am and I could still smell it on my dupatta at night. Packaging felt premium and the courier called before delivering.', 'pending', 1, NULL, NULL, '2026-09-05 20:15:00', NULL, NULL);
INSERT IGNORE INTO reviews (id, product_id, customer_name, customer_city, rating, title, body, status, is_sample, ip_hash, moderated_by, created_at, approved_at, rejected_at) VALUES (5, (SELECT p.id FROM products p WHERE p.slug = 'silver-lining'), 'Usman T.', 'Rawalpindi', 4, 'Perfect for Karachi summer', 'Bought it for a work trip to Karachi and it held up in the humidity without turning sour. Fresh and clean, exactly as described. Four stars only because the 50ml went quickly.', 'pending', 1, NULL, NULL, '2026-09-10 17:05:00', NULL, NULL);
INSERT IGNORE INTO reviews (id, product_id, customer_name, customer_city, rating, title, body, status, is_sample, ip_hash, moderated_by, created_at, approved_at, rejected_at) VALUES (6, (SELECT p.id FROM products p WHERE p.slug = 'saffron-zenith'), 'Ahmed N.', 'Multan', 5, 'Worth the price', 'Expensive but you can smell the quality. Wore it to a wedding and three people asked.', 'pending', 1, NULL, NULL, '2026-09-21 21:40:00', NULL, NULL);
INSERT IGNORE INTO reviews (id, product_id, customer_name, customer_city, rating, title, body, status, is_sample, ip_hash, moderated_by, created_at, approved_at, rejected_at) VALUES (7, (SELECT p.id FROM products p WHERE p.slug = 'eclipse-velvet'), 'Sana F.', 'Karachi', 3, 'Lovely but too strong for me', 'The tuberose and vanilla are beautiful but one spray is genuinely enough and I kept overdoing it. Would suit someone who likes a bold evening scent more than I do.', 'pending', 1, NULL, NULL, '2026-09-23 13:25:00', NULL, NULL);
INSERT IGNORE INTO reviews (id, product_id, customer_name, customer_city, rating, title, body, status, is_sample, ip_hash, moderated_by, created_at, approved_at, rejected_at) VALUES (8, (SELECT p.id FROM products p WHERE p.slug = 'nimbus-rain'), 'Faisal M.', 'Peshawar', 2, 'Not what I expected', 'I was hoping for something fresher. The wet-earth note is very realistic but it reads more like a garden after rain than a perfume to me. Delivery and packaging were fine.', 'pending', 1, NULL, NULL, '2026-09-24 09:50:00', NULL, NULL);
