INSERT IGNORE INTO content_pages (id, slug, title, heading, body, body_format, template, is_system, is_active, sort_order, seo_title, seo_description, created_at, updated_at) VALUES (1, 'about', 'About Sky Fragrances', 'More Than Just A Scent', '<p>Sky Fragrances is a Pakistani perfume house. We compose eau de parfum for the weather we actually live in: the heat of a Karachi afternoon, the dry cold of a Lahore January, the first rain of the monsoon. Every bottle is made to hold on skin for a full day, and every bottle is delivered to your door, anywhere in Pakistan.</p><h2>Named for the sky</h2><p>Each collection is a time of day. Dawn Chorus is the first light, soft florals and citrus. Azure Heights is midday air, clean and weightless. Golden Hour is the warmth before dusk, saffron, amber and rose. Midnight Meridian is our deepest work, oud, leather and smoke. Monsoon Veil is the smell of the first rain on hot ground.</p><h2>How we work</h2><p>We release slowly. A fragrance is worn on skin through Pakistani heat before it is offered for sale, and it is sold in two sizes only, 50 ml and 100 ml, so the price stays honest and the bottle stays fresh. The longevity and sillage meters on every product page are our own measurements, written down so you know what you are buying before it arrives.</p><h2>What you can count on</h2><ul><li><strong>Long-lasting.</strong> Every perfume is an eau de parfum concentration, made to survive a working day at 40 degrees.</li><li><strong>Cash on delivery, nationwide.</strong> Pay the courier at your door, or pay ahead by bank transfer, JazzCash or Easypaisa.</li><li><strong>Fast delivery.</strong> Orders are dispatched within one working day and usually arrive in two to four.</li><li><strong>Easy exchange.</strong> Sealed bottles can be exchanged within seven days of delivery. Anything damaged or wrong is replaced at our cost.</li></ul><h2>Not sure where to begin</h2><p>Take the <a href="/scent-finder">Scent Finder</a>: five questions, three recommendations, no wrong answers. If you would rather ask a person, <a href="/contact">message us on WhatsApp</a> and we will help you choose.</p>', 'html', 'page', 1, 1, 10, 'About Us | Sky Fragrances', 'Sky Fragrances is a Pakistani perfume house composing long-lasting eau de parfum for him, her and unisex, delivered nationwide with cash on delivery.', '2026-09-25 10:00:00', '2026-09-29 10:00:00');
INSERT IGNORE INTO content_pages (id, slug, title, heading, body, body_format, template, is_system, is_active, sort_order, seo_title, seo_description, created_at, updated_at) VALUES (2, 'faq', 'Frequently Asked Questions', 'Frequently Asked Questions', '<h3>How do I place an order?</h3><p>Open the fragrance you want, choose a size, add it to your cart and check out. There is no account to create: we ask only for a name, a mobile number and a delivery address. If you would rather order in a chat, tap the WhatsApp button on any product page and we will take it from there.</p><h3>Can I change or cancel my order?</h3><p>Yes, until it ships. Message us on WhatsApp with your order number and we will adjust or cancel it. Once the parcel is with the courier, the <a href="/returns">returns and exchange policy</a> applies instead.</p><h3>How long does delivery take?</h3><p>Orders are dispatched within one working day and usually arrive in two to four working days anywhere in Pakistan. Remote areas and the northern regions can take a day or two longer. The courier calls before delivering, so keep your phone reachable.</p><h3>How much is delivery?</h3><p>Delivery is a flat Rs. 250 anywhere in Pakistan, and free when the items in your order come to Rs. 3,000 or more. The fee, if any, is shown in your cart before you place the order.</p><h3>How do I track my order?</h3><p>Use the <a href="/track">Track Order</a> page with your order number and the mobile number you ordered with. Your order number is on the confirmation page and in your confirmation email. We also send a WhatsApp message with the courier and tracking number when your parcel ships.</p><h3>Do you deliver outside Pakistan?</h3><p>Not yet. We deliver to every city and town in Pakistan.</p><h3>Do you offer cash on delivery?</h3><p>Yes, nationwide. Pay the courier in cash when your parcel arrives; please keep the exact amount ready. You can also pay ahead by bank transfer, JazzCash or Easypaisa.</p><h3>How does paying by bank transfer, JazzCash or Easypaisa work?</h3><p>Choose the method at checkout and transfer the exact order total to the account shown. Enter the transaction ID from your receipt, upload a screenshot, and place the order. We verify every transfer by hand, usually within a few hours during working hours, and confirm by email and WhatsApp. An order that stays unpaid for 48 hours is cancelled and the stock is released.</p><h3>Are your perfumes long-lasting?</h3><p>Every fragrance is an eau de parfum concentration. Each product page shows a longevity and sillage meter measured on skin, so you know what to expect before you buy. Fresh, citrus compositions sit closer and softer by design; ouds and ambers carry further and stay longer.</p><h3>Are these your own perfumes?</h3><p>Yes. Every Sky Fragrances perfume is our own composition, made and bottled for us. Nothing on this site is an impression or a copy of another house.</p><h3>Which size should I choose?</h3><p>The 50 ml is three to four months of daily wear and the right way to try a fragrance for the first time. The 100 ml costs less per millilitre and is the size most customers reorder. Both are the same juice at the same concentration.</p><h3>Can I exchange or return a perfume?</h3><p>A sealed, unopened bottle can be exchanged within 7 days of delivery. A bottle that arrives damaged, leaking or different from what you ordered is replaced at our cost if you tell us within 48 hours. For hygiene reasons we cannot take back a bottle that has been opened or sprayed. The full policy is on the <a href="/returns">Returns and Exchange</a> page.</p><h3>Can I use more than one coupon?</h3><p>One coupon per order. A coupon is applied to the items subtotal, never to the delivery fee, and some codes carry a minimum order value or an expiry date.</p><h3>Do you have a shop I can visit?</h3><p>We are online only for now. If you would like advice before ordering, message us on WhatsApp and we will help you choose.</p>', 'faq', 'page-faq', 1, 1, 20, 'Frequently Asked Questions | Sky Fragrances', 'Delivery times, cash on delivery, transfers, tracking, longevity, sizes and exchanges: the questions Sky Fragrances customers ask most, answered.', '2026-09-25 10:00:00', '2026-09-29 10:00:00');
INSERT IGNORE INTO content_pages (id, slug, title, heading, body, body_format, template, is_system, is_active, sort_order, seo_title, seo_description, created_at, updated_at) VALUES (3, 'shipping', 'Shipping & Delivery', 'Shipping and Delivery', '<p>We deliver to every city and town in Pakistan through our courier partners. The figures below are our current rates; the amount shown in your cart at checkout is always the amount you pay.</p><h2>Delivery fee</h2><p>Delivery is a flat Rs. 250 anywhere in Pakistan. It is free when the items in your order come to Rs. 3,000 or more. The free-delivery bar in your cart shows how close you are.</p><h2>Dispatch and delivery time</h2><p>Orders placed before 4 pm on a working day are dispatched the same day. Orders placed later, or on a Sunday or public holiday, leave on the next working day. Delivery usually takes two to four working days. Remote areas, Azad Kashmir and Gilgit-Baltistan can take a day or two longer. Bank transfer, JazzCash and Easypaisa orders are dispatched once the payment has been verified.</p><h2>Cash on delivery</h2><p>Pay the courier in cash when your parcel arrives. Please keep the exact amount ready; riders rarely carry change. The courier calls before delivering, so keep the phone number you ordered with switched on.</p><h2>Tracking</h2><p>When your order ships we add the courier name and tracking number to it and send them to you on WhatsApp. You can see the status at any time on the <a href="/track">Track Order</a> page using your order number and phone number.</p><h2>Packaging</h2><p>Every bottle is wrapped, boxed and sealed before it leaves us. If a parcel arrives visibly damaged, photograph it before opening and contact us the same day so we can replace it.</p><h2>Missed deliveries</h2><p>The courier will attempt delivery twice and call before each attempt. If neither attempt succeeds the parcel returns to us, and we will message you to arrange re-delivery.</p>', 'html', 'page', 1, 1, 30, 'Shipping & Delivery | Sky Fragrances', 'Flat Rs. 250 delivery anywhere in Pakistan, free above Rs. 3,000. Dispatch within one working day, delivery in two to four. Cash on delivery available.', '2026-09-25 10:00:00', '2026-09-29 10:00:00');
INSERT IGNORE INTO content_pages (id, slug, title, heading, body, body_format, template, is_system, is_active, sort_order, seo_title, seo_description, created_at, updated_at) VALUES (4, 'returns', 'Returns & Exchange', 'Returns and Exchange', '<p>We want every bottle to arrive perfect. If something has gone wrong, this is how we put it right.</p><h2>Damaged, leaking or wrong item</h2><p>If your perfume arrives damaged, leaking, or is not the fragrance or size you ordered, tell us within 48 hours of delivery with your order number and a photo of the bottle and the parcel. We send a replacement at our cost and arrange collection of the original. There is nothing to pay.</p><h2>Exchange within 7 days</h2><p>A sealed, unopened bottle can be exchanged within 7 days of delivery for another fragrance or another size. The bottle must be in its original box with the seal intact. You pay the delivery cost of sending it back; we pay the delivery cost of the replacement. Any difference in price is paid by you or refunded to you before the replacement ships.</p><h2>What we cannot accept</h2><p>Perfume is a personal-care product. For hygiene reasons we cannot accept a bottle that has been opened, sprayed, or has a broken seal, whatever the reason. We also cannot accept exchanges requested more than 7 days after delivery. If you are choosing between two fragrances, the <a href="/scent-finder">Scent Finder</a> and a message on WhatsApp before you order are the safest way to get it right first time.</p><h2>Refunds</h2><p>Where a replacement is not possible we refund the amount paid. Cash-on-delivery orders are refunded by bank transfer, JazzCash or Easypaisa to an account in your name. Prepaid orders are refunded to the account they were paid from. Refunds are processed within 5 working days of the returned bottle reaching us. Delivery fees are refunded only when the fault was ours.</p><h2>Cancelled orders</h2><p>An order cancelled before it ships is refunded in full if it was prepaid, and nothing is owed if it was cash on delivery.</p><h2>How to start</h2><p>Message us on WhatsApp or use the <a href="/contact">contact page</a> with your order number and, for damage, a photo. We reply within one working day and tell you exactly what happens next.</p>', 'html', 'page', 1, 1, 40, 'Returns & Exchange | Sky Fragrances', 'Sealed bottles can be exchanged within 7 days of delivery. Damaged, leaking or wrong items are replaced at our cost within 48 hours. The full Sky Fragrances policy.', '2026-09-25 10:00:00', '2026-09-29 10:00:00');
INSERT IGNORE INTO content_pages (id, slug, title, heading, body, body_format, template, is_system, is_active, sort_order, seo_title, seo_description, created_at, updated_at) VALUES (5, 'privacy', 'Privacy Policy', 'Privacy Policy', '<p>This policy explains what Sky Fragrances collects when you use this website, what we do with it, and the choices you have. It is written to match what the site actually does.</p><h2>What we collect</h2><ul><li><strong>When you order:</strong> your name, mobile number, city, delivery address, postal code if you give one, an email address if you give one, and any note you add to the order.</li><li><strong>When you pay by bank transfer, JazzCash or Easypaisa:</strong> the transaction ID, the sender name if it differs from yours, and the payment screenshot you upload.</li><li><strong>When you contact us:</strong> your name, email address, phone number if you give one, the subject, an order number if relevant, and your message.</li><li><strong>When you join the newsletter:</strong> your email address.</li><li><strong>When you write a review:</strong> your name, city, rating and the review text. Reviews are published only after we read them.</li><li><strong>Technical:</strong> a scrambled (hashed) version of your internet address, used only to limit repeated form submissions and block spam. The raw address is not stored.</li></ul><h2>How we use it</h2><p>We use your details to process and deliver your order, to contact you about it by phone, WhatsApp or email, to verify manual payments, to reply to your messages, and to send newsletters you have asked for. We do not sell, rent or trade your information.</p><h2>Who we share it with</h2><p>Your name, phone number and address are given to the courier delivering your parcel. Nothing else is shared with anyone. This site runs no advertising or third-party analytics scripts.</p><h2>Cookies</h2><p>The site sets one cookie, which remembers your cart and protects forms from abuse. It contains no personal information and expires after three days of inactivity. Dismissing the announcement bar is remembered in your browser for the current session only.</p><h2>How long we keep it</h2><p>Order records are kept as accounting records. Payment screenshots are stored in a private area that is never publicly reachable and are removed once the order is complete and any dispute window has passed. Contact messages and reviews are kept until you ask us to delete them.</p><h2>Security</h2><p>Your details are stored on a secured server over an encrypted connection and are accessible only to the store owner. We never ask for card numbers, PINs or passwords, and no page on this site collects them.</p><h2>Your choices</h2><p>You can unsubscribe from the newsletter using the link in any email we send. You can ask us to correct or delete the details held against your orders at any time by contacting us with your order number and the phone number you ordered with.</p><h2>Changes</h2><p>We may update this policy from time to time. The date of the latest change is shown at the top of this page.</p>', 'html', 'page', 1, 1, 50, 'Privacy Policy | Sky Fragrances', 'What Sky Fragrances collects when you order, pay, write or subscribe, how it is used and protected, and how to ask for it to be deleted.', '2026-09-25 10:00:00', '2026-09-29 10:00:00');
INSERT IGNORE INTO content_pages (id, slug, title, heading, body, body_format, template, is_system, is_active, sort_order, seo_title, seo_description, created_at, updated_at) VALUES (6, 'terms', 'Terms & Conditions', 'Terms and Conditions', '<p>By placing an order on this website you agree to the terms below. They are short on purpose; if anything is unclear, ask us before you order.</p><h2>Orders</h2><p>An order is accepted when we confirm it by phone, WhatsApp or email, or when it is dispatched, whichever comes first. We may decline or cancel an order if a fragrance is out of stock, if the delivery address cannot be served, if a price or description was shown in error, or if we suspect fraud. If we cancel a prepaid order, the full amount is refunded.</p><h2>Prices</h2><p>All prices are in Pakistani rupees and include all applicable taxes. The price charged is the price shown at the time you place your order; delivery is charged as shown at checkout. We may change prices at any time, but a change never affects an order already placed.</p><h2>Payment</h2><p>We accept cash on delivery, bank transfer, JazzCash and Easypaisa. Cash-on-delivery orders are paid to the courier in cash on arrival. Transfer orders must be paid in full to the account shown at checkout, with the transaction ID and a screenshot provided; they are verified by us before dispatch. A transfer order that remains unpaid 48 hours after it was placed is cancelled and the stock is released. If a cash-on-delivery parcel is refused or cannot be delivered after two attempts, we may ask for advance payment on future orders.</p><h2>Delivery</h2><p>Delivery times are estimates and are not guaranteed. Responsibility for the goods passes to you when the parcel is handed over. Please inspect the parcel on arrival and report any damage within 48 hours as set out in our <a href="/returns">Returns and Exchange</a> policy, which forms part of these terms.</p><h2>Coupons</h2><p>Coupon codes apply to the items subtotal only, are limited to one per order, may carry a minimum order value, an expiry date, a usage limit and a one-per-customer limit, and may be withdrawn at any time. A coupon is redeemed when the order is placed.</p><h2>Reviews and content</h2><p>Reviews are published only after we have read them, and we may decline or shorten a review. By submitting one you allow us to display it with your first name and city. All other text, images and branding on this site belong to Sky Fragrances and may not be reproduced without permission.</p><h2>Accuracy</h2><p>We describe every fragrance as honestly as we can, but scent is personal and the same perfume behaves differently on different skin. Photographs are for illustration; bottle and packaging details may change between batches.</p><h2>Liability</h2><p>Our liability for any order is limited to the amount you paid for it. Nothing in these terms limits any right you have under the consumer protection laws of Pakistan, which govern these terms.</p><h2>Contact</h2><p>Questions about these terms can be sent through the <a href="/contact">contact page</a> or on WhatsApp.</p>', 'html', 'page', 1, 1, 60, 'Terms & Conditions | Sky Fragrances', 'The terms that apply when you order from Sky Fragrances: orders, prices, payment, delivery, exchanges and coupons, under the laws of Pakistan.', '2026-09-25 10:00:00', '2026-09-29 10:00:00');
